function setupFlowMotion(){
 const scene=document.querySelector('.flow-scene'),back=scene?.querySelector('.flow-plane-back'),front=scene?.querySelector('.flow-plane-front');
 if(!back||!front)return;
 const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
 const renderFrame=now=>{
  if(document.hidden||motionPreference.matches){flowFrame=0;return;}
  if(now-flowLastFrame<1000/30){flowFrame=requestAnimationFrame(renderFrame);return;}
  flowLastFrame=now;const elapsed=(now-flowStartTime)/1000,width=window.innerWidth;
  const slow=elapsed*Math.PI*2/12,fast=elapsed*Math.PI*2/7.5;
  const x=Math.sin(slow)*Math.min(width*.12,70),y=Math.cos(slow*.8)*Math.min(width*.07,36);
  const edge=Math.sin(fast)*Math.min(width*.085,50),crest=Math.cos(fast*.86)*Math.min(width*.06,30);
  back.style.transform=`translate3d(${x}px,${y}px,-70px) scale(1.2) rotate(${Math.sin(slow)*1.8}deg)`;
  front.style.transform=`translate3d(${-edge}px,${crest}px,35px) scale(1.16) rotate(${Math.cos(fast)*1.2}deg)`;
  front.style.opacity=String(.56+((Math.sin(fast)+1)/2)*.34);
  flowFrame=requestAnimationFrame(renderFrame);
 };
 const stop=()=>{if(flowFrame)cancelAnimationFrame(flowFrame);flowFrame=0;};
 const start=()=>{stop();if(document.hidden||motionPreference.matches)return;flowStartTime=performance.now();flowLastFrame=0;flowFrame=requestAnimationFrame(renderFrame);};
 const applyMotionPreference=()=>{stop();if(motionPreference.matches){back.style.transform='translate3d(0,0,-70px) scale(1.2)';front.style.transform='translate3d(0,0,35px) scale(1.16)';front.style.opacity='.58';}else start();};
 document.addEventListener('visibilitychange',()=>document.hidden?stop():start());
 motionPreference.addEventListener?.('change',applyMotionPreference);
 applyMotionPreference();
}
