async function markRefunded(id){try{await apiFunction('admin',{action:'mark_refunded',order_id:id});await refreshOrders();render();toast('Order marked refunded.');}catch(e){reportActionError(e);}}
function addListingCredentialsModal(id){const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<section class="modal glass" role="dialog" aria-modal="true" aria-labelledby="extra-credential-title"><div class="listing-meta"><h2 id="extra-credential-title">Add account credentials</h2><button class="icon-button" data-action="close-modal" aria-label="Close">×</button></div><p class="muted">This entry is encrypted before it is saved. Existing credentials stay encrypted.</p><form id="listing-credentials-form" data-id="${esc(id)}"><div class="form-field"><label for="extra-label">Label</label><input class="input" id="extra-label" name="label" maxlength="80" required placeholder="e.g. Game login"></div><div class="form-field"><label for="extra-username">Username</label><input class="input" id="extra-username" name="login" maxlength="300" required></div><div class="form-field"><label for="extra-password">Password</label><input class="input" id="extra-password" name="password" type="password" maxlength="1000" required></div><div class="form-field"><label for="extra-recovery">Recovery details (optional)</label><input class="input" id="extra-recovery" name="recovery" maxlength="1000"></div><div class="form-field"><label for="extra-notes">Notes (optional)</label><textarea class="textarea" id="extra-notes" name="notes" maxlength="2000"></textarea></div><button class="button button-primary full-width">Save encrypted entry</button></form></section>`;document.body.append(backdrop);}
async function saveListingCredentials(form){if(state.role!=='owner')throw new Error('Only the owner can add listing credentials.');const input=form.elements;await apiFunction('admin',{action:'add_listing_credentials',listing_id:form.dataset.id,credentials:[{label:input.label.value,login:input.login.value,password:input.password.value,recovery:input.recovery.value,notes:input.notes.value}]});form.closest('.modal-backdrop')?.remove();await refreshAdminData();render();toast('Credential entry encrypted and saved.');}function buyerSellModal(){const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<section class="modal glass" role="dialog" aria-modal="true"><div class="listing-meta"><h2>Submit an account</h2><button class="icon-button" data-action="close-modal" aria-label="Close">×</button></div><p class="muted">Submissions stay in draft until reviewed and published.</p><form id="buyer-sell-form"><div class="form-field"><label for="sell-game">Game</label><select class="select" id="sell-game" name="game">${GAMES.map(g=>`<option>${esc(g)}</option>`).join('')}</select></div><div class="form-field"><label for="sell-price">Price in NGN</label><input class="input" id="sell-price" name="price" type="number" min="1" step="1" required></div><div class="form-field"><label for="sell-description">Description</label><textarea class="textarea" id="sell-description" name="description" maxlength="700" required></textarea></div><p class="muted">Credentials are encrypted before storage.</p><div class="form-field"><label for="sell-login">Login</label><input class="input" id="sell-login" name="login" required></div><div class="form-field"><label for="sell-password">Password</label><input class="input" id="sell-password" name="password" type="password" required></div><div class="form-field"><label for="sell-recovery">Recovery notes</label><input class="input" id="sell-recovery" name="recovery"></div><button class="button button-primary full-width">Submit for review</button></form></section>`;document.body.append(backdrop);}
async function flagChanged(input){if(state.role!=='owner'){input.checked=!input.checked;toast('Only the owner can change feature flags.','error');return;}const key=input.dataset.flag,enabled=input.checked;if(!state.backend){state.flags[key]=enabled;toast('Preview only. Supabase is not connected.');render();return;}try{await apiFunction('admin',{action:'set_flag',key,enabled});state.flags[key]=enabled;toast('Feature flag saved and logged.');render();}catch(e){input.checked=!enabled;reportActionError(e);}}
async function addAdmin(form){if(!state.backend)return toast('Connect Supabase to manage users.','error');try{await apiFunction('admin',{action:'add_admin',email:form.elements.email.value});form.reset();toast('Admin role assigned.');}catch(e){reportActionError(e);}}
function countdownTick(){document.querySelectorAll('[data-countdown]').forEach(el=>{const ms=Math.max(0,new Date(el.dataset.countdown)-Date.now());const sec=Math.floor(ms/1000);el.textContent=`${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec%3600/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;if(ms===0)el.closest('.cart-item')?.remove();});}
function startCountdowns(){clearInterval(countdownTimer);countdownTick();countdownTimer=setInterval(countdownTick,1000);}
let otpTimer,countdownTimer;function startOtpTimer(){clearInterval(otpTimer);let n=60;const el=document.querySelector('#resend-count');if(el)el.textContent=n;otpTimer=setInterval(()=>{n=Math.max(0,n-1);const target=document.querySelector('#resend-count');if(target)target.textContent=n;if(n===0)clearInterval(otpTimer);},1000);}
document.addEventListener('click',async event=>{const t=event.target.closest('[data-nav],[data-action],[data-filter-game],[data-admin-tab],[data-listing-action]');if(!t)return;try{
 if(t.dataset.nav){await navTo(t.dataset.nav);return;}if(t.dataset.filterGame){state.filters.game=t.dataset.filterGame;render();return;}if(t.dataset.adminTab){state.adminTab=t.dataset.adminTab;const content=app.querySelector('.admin-content');if(content)content.innerHTML=adminScreen(true);app.querySelectorAll('.admin-nav').forEach(button=>{const active=button.dataset.adminTab===state.adminTab;button.classList.toggle('active',active);button.setAttribute('aria-current',active?'page':'false');});syncFeatureElements();return;}if(t.dataset.listingAction==='cart'){const listing=state.listings.find(item=>String(item.id)===String(t.dataset.id));const days=listing?.delivery_type==='rental'?Number(document.querySelector('#rental-duration')?.value):null;t.closest('.modal-backdrop')?.remove();await addToCart(t.dataset.id,days);return;}if(t.dataset.listingAction==='details'){showListingDetails(t.dataset.id);return;}
 const action=t.dataset.action;if(action==='enable-push'){await enablePush();return;}if(action==='disable-push'){await disablePush();return;}if(action==='install-app'){if(!deferredInstallPrompt||appInstalled)return;const promptEvent=deferredInstallPrompt;deferredInstallPrompt=null;await promptEvent.prompt();const choice=await promptEvent.userChoice;if(choice?.outcome==='accepted'){appInstalled=true;render();toast('Arcade Store is installed.');}else if(state.screen==='Settings')render();return;}if(action==='game-select'){state.filters.game=t.dataset.game;state.filters.status='all';setScreen('Market');return;}
 if(action==='signup'||action==='signin'){state.authTab=action;setScreen('auth');return;}if(action==='auth-tab'){switchAuthTab(t.dataset.tab);return;}if(action==='google-signin'){await signinGoogle();return;}if(action==='forgot'){await forgotPassword();return;}if(action==='help'){showSupport();return;}
 if(action==='resend'){if(document.querySelector('#resend-count')?.textContent!=='0')return toast('Please wait for the timer to finish.');if(state.backend){const {error}=await state.client.auth.resend({type:state.otpMode==='recovery'?'recovery':'signup',email:state.email});if(error)throw error;}toast('If this address is registered, a new code is on its way.');startOtpTimer();return;}
 if(action==='remove-cart'){if(t.dataset.reservationStatus==='checkout'&&!window.confirm('Cancel this payment attempt and release the reservation? If the payment arrives later, it will be flagged for a refund.'))return;await removeFromCart(t.dataset.id);return;}if(action==='checkout'){await checkout();return;}
 if(action==='logout'){if(state.backend)await state.client.auth.signOut();clearInterval(state.ordersTimer);state.session=null;state.user=null;state.profile=null;state.role='guest';state.cart=[];state.orders=[];state.vendorListings=[];state.vendorOrders=[];state.vendorProfile=null;state.adminListings=[];state.adminOrders=[];state.adminSales=[];state.adminUsers=[];setScreen('home');return;}
 if(action==='admin'){if(!['owner','admin'].includes(state.role)){toast('Admin access only.','error');return;}state.adminTab='Dashboard';await navTo('Admin');return;}if(action==='new-listing'){newListingModal();return;}if(action==='add-listing-credentials'){if(state.role!=='owner')throw new Error('Owner only.');addListingCredentialsModal(t.dataset.id);return;}if(action==='admin-release-reservation'){if(state.role!=='owner')throw new Error('Owner only.');const pending=t.dataset.reservationStatus==='checkout';const promptText=pending?'Remove this reservation and cancel its payment attempt? A payment that succeeds later will require a refund.':'Remove this reservation so the account is available again?';if(!window.confirm(promptText))return;await apiFunction('admin',{action:'release_reservation',reservation_id:t.dataset.id});await refreshAdminData();await refreshMarket();await refreshCart();render();toast('Reservation removed; account is available again.');return;}if(action==='buyer-sell'){if(!state.flags.buyer_selling){toast('Buyer selling is currently disabled.','error');return;}buyerSellModal();return;}if(action==='close-modal'){t.closest('.modal-backdrop')?.remove();return;}
 if(action==='credentials'){await viewCredentials(t.dataset.id);return;}if(action==='mark-refunded'){await markRefunded(t.dataset.id);return;}if(action==='check-payment'){await apiFunction('payment-reconcile',{order_id:t.dataset.id});await refreshAdminData();render();toast('Payment status checked.');return;}
 if(action==='publish-listing'||action==='hide-listing'||action==='delete-listing'){if(action==='delete-listing'&&!window.confirm('Delete this listing? Credentials will be erased.'))return;const endpointAction=action==='publish-listing'?'publish_listing':action==='hide-listing'?'hide_listing':'delete_listing';await apiFunction('admin',{action:endpointAction,listing_id:t.dataset.id});await refreshAdminData();render();toast(action==='delete-listing'?'Listing deleted and credentials erased.':'Listing updated.');return;}
 if(action==='remove-admin'){if(!window.confirm(`Remove admin access for ${t.dataset.email}?`))return;await apiFunction('admin',{action:'remove_admin',email:t.dataset.email});await refreshAdminData();render();toast('Admin access removed.');return;}
 }catch(e){reportActionError(e);}});
document.addEventListener('submit',async event=>{event.preventDefault();const f=event.target;try{
 if(f.id==='auth-form'){if(!validateForm(f))return;const mode=f.dataset.mode,identifier=f.elements.identifier.value.trim(),password=f.elements.password.value;if(mode==='signup')await signup(f.elements.username.value.trim(),identifier,password);else await signin(identifier,password);return;}
 if(f.id==='otp-form'){const code=[...f.querySelectorAll('[data-otp]')].map(x=>x.value).join('');if(!/^\d{6}$/.test(code)){f.querySelector('[data-error="otp"]').textContent='Enter all six digits.';return;}await verifyCode(code);return;}
 if(f.id==='reset-form'){const password=f.elements.new_password.value;if(password.length<10){validation('new_password','Use at least 10 characters.');return;}if(state.backend){const {error}=await state.client.auth.updateUser({password});if(error)throw error;}state.session=null;state.user=null;state.role='guest';state.authTab='signin';setScreen('auth');toast('Password updated. Sign in with your new password.');return;}
   if(f.id==='new-listing-form'){await createListing(event.submitter?.value==='true');return;}if(f.id==='listing-credentials-form'){await saveListingCredentials(f);return;}
 if(f.id==='buyer-sell-form'){if(!state.flags.buyer_selling)throw new Error('Buyer selling is currently disabled.');const result=await apiFunction('buyer-sell',{game:f.elements.game.value,price:Number(f.elements.price.value),description:f.elements.description.value,credentials:[{label:'Account login',login:f.elements.login.value,password:f.elements.password.value,recovery:f.elements.recovery.value}]});f.closest('.modal-backdrop')?.remove();toast(`Account submitted for review (${result.listing_id}).`);return;}
 if(f.id==='admin-user-form'){await addAdmin(f);return;}
 }catch(e){reportActionError(e);}});
document.addEventListener('input',event=>{const t=event.target;if(t.matches('#search-listings')){state.filters.query=t.value;const target=document.querySelector('#listing-results');if(target){const rows=filteredListings();target.innerHTML=rows.length?rows.map(listingCard).join(''):'<div class="empty-state glass" style="grid-column:1/-1"><div class="empty-icon">⌕</div><h3>No accounts match those filters</h3><p>Try another game or adjust the price range.</p></div>';}}if(t.name)validation(t.name,'');if(t.matches('[data-otp]')){t.value=t.value.replace(/\D/g,'').slice(-1);const all=[...document.querySelectorAll('[data-otp]')];if(t.value&&all[t.dataset.otp-0+1])all[t.dataset.otp-0+1].focus();}});
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='price-filter'){state.filters.price=t.value;render();}if(t.id==='status-filter'){state.filters.status=t.value;render();}if(t.dataset.flag)await flagChanged(t);});
document.addEventListener('keydown',event=>{if(event.target.matches('[data-otp]')&&event.key==='Backspace'&&!event.target.value){const all=[...document.querySelectorAll('[data-otp]')];all[Math.max(0,event.target.dataset.otp-1)]?.focus();}if(event.key==='Escape')document.querySelector('.modal-backdrop')?.remove();});
document.addEventListener('click',async event=>{const t=event.target.closest('[data-action],[data-vendor-tab]');if(!t)return;const action=t.dataset.action;try{
 if(t.dataset.vendorTab){state.vendorTab=t.dataset.vendorTab;render();return;}
 if(action==='vendor-console'){state.vendorTab='Overview';await navTo('Vendor');return;}if(action==='vendor-logout'){await state.client?.auth.signOut();state.session=null;state.user=null;state.profile=null;state.role='guest';state.cart=[];state.orders=[];state.vendorListings=[];state.vendorOrders=[];state.vendorProfile=null;setScreen('home');return;}
 if(action==='edit-listing'){const id=t.dataset.id||t.closest('[data-listing-id]')?.dataset.listingId;if(!id)throw new Error('listing is missing');const endpoint=state.role==='vendor'?'vendor':'admin',listing=await apiFunction(endpoint,{action:'get_listing',listing_id:id});newListingModal(listing);return;}
 if(['publish-listing','hide-listing','delete-listing'].includes(action)){if(action==='delete-listing'&&!confirm('Delete this listing?'))return;const endpoint=state.role==='vendor'?'vendor':'admin',op=action==='publish-listing'?'publish_listing':action==='hide-listing'?'hide_listing':'delete_listing';await apiFunction(endpoint,{action:op,listing_id:t.dataset.id});await refreshMarket();if(state.role==='vendor')await refreshVendorData();else await refreshAdminData();render();toast('Listing updated.');return;}
 if(action==='add-credential'){document.querySelector('#credential-entry-list')?.insertAdjacentHTML('beforeend',credentialInputRow());return;}if(action==='remove-credential'){t.closest('.credential-entry')?.remove();return;}if(action==='add-rental-option'){document.querySelector('#rental-option-list')?.insertAdjacentHTML('beforeend',rentalOptionRow({duration_days:'',price:''}));return;}if(action==='remove-rental-option'){t.closest('.rental-option-entry')?.remove();return;}
 if(action==='open-chat'){await openOrderChat(t.dataset.id);return;}if(action==='close-modal'&&activeChatOrder){activeChatOrder=null;clearTimeout(chatReconnectTimer);if(activeChatChannel){await state.client.removeChannel(activeChatChannel);activeChatChannel=null;}return;}
 if(action==='mark-delivered'){await chatApi({action:'mark_delivered',order_id:t.dataset.id});toast('Delivery marked complete.');await openOrderChat(t.dataset.id);if(state.role==='vendor')await refreshVendorData();else await refreshAdminData();return;}
 }catch(error){reportActionError(error);}});
document.addEventListener('change',async event=>{const target=event.target;if(target.id==='delivery-type'){const editor=document.querySelector('#rental-editor');if(editor)editor.hidden=target.value!=='rental';}if(target.matches('#order-chat-form [name=image]')){try{await uploadChatImage(target.form,target.files?.[0]);target.value='';}catch(error){reportActionError(error);}}});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id==='vendor-profile-form'){event.preventDefault();try{await apiFunction('admin',{action:'set_vendor_profile',email:form.elements.email.value,flw_subaccount_id:form.elements.subaccount.value,verified_partner:form.elements.verified_partner.checked});form.reset();toast('Vendor access saved. Ask them to sign in again to open the Vendor console.');}catch(error){reportActionError(error);}return;}if(form.id==='order-chat-form'){event.preventDefault();const message=form.elements.message.value.trim();if(!message)return;if(/\b(?:your|own|personal)\s+(?:email|gmail|icloud|outlook|account)\s+(?:password|passcode)\b|\b(?:send|share|tell|give)\s+(?:me\s+)?(?:your|own|personal)\s+(?:email|gmail|icloud|outlook|account)\s+(?:password|passcode)\b/i.test(message)&&!window.confirm('This sounds like a request for someone else’s personal email or account password. Only share information needed for the transfer. Send this message anyway?'))return;const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{const result=await chatApi({action:'send_text',order_id:form.dataset.orderId,message});await appendChatMessage(result.message);form.reset();}catch(error){reportActionError(error);}finally{if(button)button.disabled=false;}return;}});
async function handlePaymentReturn(){const params=new URLSearchParams(window.location.search);if(params.get('payment_return')!=='1')return;const orderId=params.get('order_id');try{if(state.backend&&state.session&&orderId){const result=await apiFunction('payment-reconcile',{order_id:orderId});await refreshOrders();await refreshCart();await refreshMarket();setScreen('Orders');if(result.ok||result.status==='paid')toast('Payment confirmed. Open your order to view account details.');else if(result.status==='cancelled'||params.get('status')==='cancelled'||params.get('status')==='failed')toast('Payment cancelled. Your reservation stays in Cart; retry or remove it before expiry.');else if(result.status==='expired')toast('This payment attempt expired. Your reservation stays in Cart until its 24-hour timer ends.');else toast('We are checking your payment. Your order will update shortly.');}else{toast('Sign in again to check your payment status.','error');setScreen(state.session?'Orders':'home');}}catch(e){toast('We could not confirm payment yet. Open Orders to check again.','error');setScreen('Orders');}finally{for(const key of ['payment_return','order_id','status','tx_ref','transaction_id'])params.delete(key);const clean=`${window.location.pathname}${params.size?'?'+params.toString():''}${window.location.hash}`;window.history.replaceState({},'',clean);}}
function setupInstallAndOffline(){const offlineNotice=document.querySelector('#offline-status');const syncNetworkStatus=()=>{if(offlineNotice)offlineNotice.hidden=navigator.onLine;};syncNetworkStatus();window.addEventListener('online',syncNetworkStatus);window.addEventListener('offline',syncNetworkStatus);window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;if(state.screen==='Settings')render();});window.addEventListener('appinstalled',()=>{appInstalled=true;deferredInstallPrompt=null;if(state.screen==='Settings')render();});if('serviceWorker'in navigator){navigator.serviceWorker.register(new URL('../service-worker.js',import.meta.url),{scope:new URL('../',import.meta.url).pathname}).catch(()=>{if(offlineNotice&&!navigator.onLine)offlineNotice.hidden=false;});}}
setupInstallAndOffline();
async function init(){setupFlowMotion();await loadBackend();if(state.backend){await loadFlags();}if(state.backend&&state.session){if(state.screen==='home')setScreen('Market');else render();await handlePaymentReturn();}else{setScreen('home');if(new URLSearchParams(window.location.search).get('payment_return')==='1')await handlePaymentReturn();}}
init();

document.addEventListener('change',async event=>{const input=event.target;if(!input.matches('[data-push-preference]'))return;try{await savePushPreference(input);}catch(error){reportActionError(error);}});
